const cliente = $items("Webhook RPA")[0].json;
const csvData = $input.all()[0].json.data;

// Lógica para definir a mensagem de acordo com o perfil
let recomendacao = "";
if (cliente.perfil === "Conservador") {
  recomendacao = "Recomendamos Tesouro Direto e CDBs de liquidez diária.";
} else if (cliente.perfil === "Moderado") {
  recomendacao = "Recomendamos uma carteira mista com Fundos Multimercado e CDBs.";
} else {
  recomendacao = "Recomendamos diversificação em Ações e Fundos Imobiliários (FIIs).";
}

// Retornar os dados cruzados e prontos para envio
return {
  json: {
    nome_cliente: cliente.nome,
    email: cliente.email,
    perfil_investidor: cliente.perfil,
    saldo_atual: cliente.saldo,
    mensagem_sugerida: `Olá, ${cliente.nome}! Analisamos o seu perfil ${cliente.perfil} e seu saldo atual de ${cliente.saldo}. ${recomendacao}`
  }
};
